      de: "Eine der wichtigsten buddhistischen Pilgerstätten in Myanmar, die eine hoch verehrte Buddha-Statue beherbergt.",
      hu: "Mianmar egyik legfontosabb buddhista zarándokhelye, amely egy nagyon tisztelt Buddha-szobornak ad otthont.",
      ro: "Unul dintre cele mai importante locuri de pelerinaj budist din Myanmar, adăpostind o statuie a lui Buddha foarte venerată.",
      en: "One of the most important Buddhist pilgrimage sites in Myanmar, housing a highly venerated Buddha statue.",
      es: "Uno de los lugares de peregrinación budista más importantes de Myanmar, que alberga una estatua de Buda muy venerada.",
      pt: "Um dos locais de peregrinação budista mais importantes de Myanmar, que abriga uma estátua de Buda altamente venerada.",
      fr: "L'un des sites de pèlerinage bouddhistes les plus importants du Myanmar, abritant une statue de Bouddha très vénérée.",
