    descriptionAdvanced: {
      de: "Die Kakku-Pagoden im südlichen Shan-Staat sind ein faszinierendes Ensemble von über 2400 Stupas, das tief im Territorium des Pa-O-Volkes liegt. Die Ursprünge der Stätte reichen bis ins 12. Jahrhundert zurück, wobei die Legende den Bau dem König Alaungsithu von Bagan zuschreibt. Die meisten der heute sichtbaren Strukturen stammen jedoch aus dem 17. und 18. Jahrhundert und zeigen eine einzigartige Mischung aus Shan- und Bagan-Architekturstilen. Die Pagoden stehen in extrem dichten Reihen auf einer relativ kleinen Fläche, was einen beeindruckenden Wald aus Spitzen erzeugt, die im Wind klingen. Jede Stupa ist mit kunstvollen Stuckverzierungen geschmückt, die florale Motive, mythologische Wesen und buddhistische Symbole darstellen. Nach jahrelanger Vernachlässigung wurde der Komplex im Jahr 2001 umfassend restauriert und für die Öffentlichkeit zugänglich gemacht. Jedes Jahr im März findet hier das Kakku-Pagodenfest statt, bei dem Tausende Pa-O in ihren traditionellen schwarzen Trachten zusammenkommen, um ihre kulturelle und religiöse Identität zu feiern.",
      hu: "A dél-Sán államban található Kakku-pagodák egy több mint 2400 sztúpából álló lenyűgöző együttes, amely a Pa-O nép területén fekszik. A helyszín eredete a 12. századig nyúlik vissza, a legenda szerint Alaungsithu bagani király rendelte el az első építkezéseket. A ma látható struktúrák többsége azonban a 17. és 18. századból származik, és a sán, valamint a bagani építészeti stílusok egyedi keveredését mutatja. A pagodák rendkívül sűrű sorokban állnak egy viszonylag kis területen, ami egyfajta „csúcsok erdejét” alkotja, amelyek a szélben megkonduló harangjaikkal különleges hangulatot árasztanak. Minden sztúpát gazdag stukkódíszítés ékesít, amely virágmotívumokat, mitológiai lényeket és buddhista szimbólumokat ábrázol. Évtizedes elhanyagoltság után a komplexumot 2001-ben átfogóan felújították és megnyitották a nagyközönség előtt. Minden év márciusában itt tartják a Kakku-pagodafesztivált, ahol Pa-O emberek ezrei gyűlnek össze hagyományos fekete népviseletükben, hogy megünnepeljék vallási és kulturális örökségüket.",
      ro: "Pagodele Kakku din statul Shan de Sud reprezintă un ansamblu fascinant de peste 2400 de stupe, situat adânc în teritoriul poporului Pa-O. Originile sitului datează din secolul al XII-lea, legenda atribuind construcția regelui Alaungsithu din Bagan. Totuși, majoritatea structurilor vizibile astăzi au fost ridicate în secolele al XVII-lea și al XVIII-lea, prezentând un amestec unic de stiluri arhitecturale Shan și Bagan. Pagodele sunt dispuse în rânduri extrem de dense pe o suprafață relativ mică, creând efectul unei păduri de turle ale căror clopoței sună în bătaia vântului. Fiecare stupa este împodobită cu decorațiuni complexe în stuc, reprezentând motive florale, ființe mitologice și simboluri budiste. După ani de neglijare, complexul a fost restaurat masiv în anul 2001 și deschis publicului larg. În fiecare an, în luna martie, are loc festivalul pagodelor Kakku, unde mii de membri ai comunității Pa-O se adună în costumele lor tradiționale negre pentru a celebra identitatea lor culturală și religioasă.",
      en: "The Kakku Pagodas in Southern Shan State are a mesmerizing ensemble of over 2400 stupas located deep within the territory of the Pa-O people. The origins of the site date back to the 12th century, with legend attributing the initial construction to King Alaungsithu of Bagan. However, most of the structures seen today were built during the 17th and 18th centuries, showcasing a unique blend of Shan and Bagan architectural styles. The pagodas stand in extremely dense rows across a relatively small area, creating a forest of spires whose bells tinkle in the wind. Each stupa is adorned with intricate stucco carvings depicting floral motifs, mythological creatures, and Buddhist symbols. After decades of neglect, the complex underwent a major restoration in 2001 and was opened to the public. Every year in March, the Kakku Pagoda Festival takes place, drawing thousands of Pa-O people in their traditional black attire to celebrate their religious and cultural heritage.",
      es: "Las pagodas de Kakku son una colección de más de 2.500 estupas en el estado de Shan en Myanmar, a unos 40 km al sur de Taunggyi. Las estupas están dispuestas en filas apretadas y datan de los siglos XVI al XVIII. Están construidas en estilo Mon, con múltiples pináculos y sombrillas en forma de campana. Según la leyenda, fueron fundadas por el rey Alaungsithu en el siglo XII. El sitio está rodeado por un muro y es venerado como sagrado por el pueblo Pa-O. Se realizan peregrinaciones anuales durante el festival de la luna llena. Las pagodas de Kakku ofrecen una vista impresionante.",
      pt: "As pagodes de Kakku são uma coleção de mais de 2.500 stupas no Estado de Shan, em Myanmar, a cerca de 40 km ao sul de Taunggyi. As stupas estão densamente alinhadas e datam dos séculos XVI a XVIII. Foram construídas no estilo Mon, com múltiplos pináculos e guarda-sóis em forma de sino. Segundo a lenda, foram fundadas pelo rei Alaungsithu no século XII. O local é cercado por um muro e é venerado como sagrado pelo povo Pa-O. Peregrinações anuais ocorrem durante o festival da lua cheia. As pagodes de Kakku oferecem uma visão impressionante.",
      fr: "Les pagodes de Kakku sont un ensemble de plus de 2 500 stupas dans l'État Shan au Myanmar, à environ 40 km au sud de Taunggyi. Les stupas sont serrés les uns contre les autres et datent du XVIe au XVIIIe siècle. Ils sont construits dans le style Mon, avec plusieurs pinacles et des parasols en forme de cloche. Selon la légende, ils ont été fondés par le roi Alaungsithu au XIIe siècle. Le site est entouré d'un mur et est vénéré comme sacré par le peuple Pa-O. Des pèlerinages annuels ont lieu pendant le festival de la pleine lune. Les pagodes de Kakku offrent un spectacle impressionnant.",
    },
